package com.primehr.succession.api;
import com.primehr.security.*;import com.primehr.succession.application.SuccessionReadinessService;import com.primehr.succession.api.SuccessionReadinessDtos.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/primehr/v1/succession/readiness")public class SuccessionReadinessController{
 private final SuccessionReadinessService service;private final SuccessionPlanningPermissionGuard permission;private final AgencyScopeResolver agency;
 public SuccessionReadinessController(SuccessionReadinessService service,SuccessionPlanningPermissionGuard permission,AgencyScopeResolver agency){this.service=service;this.permission=permission;this.agency=agency;}
 @GetMapping public List<AssessmentResponse>list(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){var s=permission.require(SuccessionPlanningPermissionGuard.READINESS,PrimeHrAction.ACCESS,t);return service.list(agency.resolveAgencyId(a),a.getName(),s);}
 @GetMapping("/{id}")public AssessmentResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){var s=permission.require(SuccessionPlanningPermissionGuard.READINESS,PrimeHrAction.ACCESS,t);return service.get(agency.resolveAgencyId(a),id,a.getName(),s);}
 @PostMapping("/candidates/{candidateId}")@ResponseStatus(HttpStatus.CREATED)public AssessmentResponse initialize(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String candidateId,@Valid@RequestBody InitializeInput i){var s=permission.require(SuccessionPlanningPermissionGuard.READINESS,PrimeHrAction.EDIT,t);return service.initialize(agency.resolveAgencyId(a),candidateId,i,t,a.getName(),s,c);}
 @PostMapping("/{id}/assignments/{assignmentId}/conflict")public AssessmentResponse conflict(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String assignmentId,@Valid@RequestBody ConflictInput i){var s=permission.require(SuccessionPlanningPermissionGuard.READINESS,PrimeHrAction.EDIT,t);return service.declareConflict(agency.resolveAgencyId(a),id,assignmentId,i,a.getName(),s,c);}
 @PostMapping("/{id}/assignments/{assignmentId}/replacement")public AssessmentResponse replace(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String assignmentId,@Valid@RequestBody ReplacementInput i){var s=permission.require(SuccessionPlanningPermissionGuard.READINESS,PrimeHrAction.EDIT,t);return service.replace(agency.resolveAgencyId(a),id,assignmentId,i,a.getName(),s,c);}
 @PutMapping("/{id}/findings")public AssessmentResponse findings(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody FindingsInput i){var s=permission.require(SuccessionPlanningPermissionGuard.READINESS,PrimeHrAction.EDIT,t);return service.findings(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping("/{id}/recommendation")public AssessmentResponse recommend(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody RecommendationInput i){var s=permission.require(SuccessionPlanningPermissionGuard.READINESS,PrimeHrAction.SUBMIT,t);return service.recommend(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
 @PostMapping("/{id}/decision")public AssessmentResponse decide(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody DecisionInput i){var s=permission.require(SuccessionPlanningPermissionGuard.READINESS,PrimeHrAction.FINALIZE,t);return service.decide(agency.resolveAgencyId(a),id,i,t,a.getName(),s,c);}
}
